<?php
$resident=warga_for_user(user_id());$rows=[];$histories=[];if($resident){$s=db()->prepare('SELECT * FROM pengajuan WHERE data_warga_id=? ORDER BY created_at DESC');$s->execute([$resident['id']]);$rows=$s->fetchAll();foreach($rows as $row){$h=db()->prepare('SELECT status,catatan,created_at FROM pengajuan_status_history WHERE pengajuan_id=? ORDER BY created_at');$h->execute([$row['id']]);$histories[$row['id']]=$h->fetchAll();}}
?>
<div class="page-heading"><div><h1>Riwayat Pengajuan</h1><p>Pantau status seluruh permohonan administrasi yang pernah kamu kirim.</p></div><a href="<?= e(url('ajukan')) ?>" class="btn btn-army"><i class="bi bi-plus-lg me-2"></i>Ajukan Baru</a></div>
<div class="d-flex flex-column gap-3"><?php if(!$rows): ?><div class="panel-card empty-state"><i class="bi bi-clock-history"></i><strong>Belum ada riwayat pengajuan</strong><span>Pengajuan administrasi yang kamu kirim akan ditampilkan di sini.</span><a href="<?= e(url('ajukan')) ?>" class="btn btn-army mt-3">Mulai Pengajuan</a></div><?php else: foreach($rows as $p): ?><section class="panel-card"><div class="panel-card-body"><div class="d-flex flex-wrap justify-content-between align-items-start gap-2"><div><small class="text-muted-2"><?= e($p['nomor_pengajuan']) ?></small><h2 class="h5 fw-bold mt-1 mb-1"><?= e($p['nama_layanan']) ?></h2><p class="text-muted-2 small mb-0"><?= e($p['keperluan']) ?></p></div><?= status_badge($p['status']) ?></div><div class="d-flex flex-wrap justify-content-between gap-3 mt-3 pt-3 border-top"><small class="text-muted-2">Diajukan <?= e(format_datetime($p['diajukan_pada'])) ?></small><button class="btn btn-sm btn-outline-army" type="button" data-bs-toggle="collapse" data-bs-target="#history<?= $p['id'] ?>">Lihat perkembangan <i class="bi bi-chevron-down ms-1"></i></button></div><div class="collapse mt-3" id="history<?= $p['id'] ?>"><div class="timeline ms-2 mt-2"><?php foreach($histories[$p['id']]??[] as $h): ?><div class="timeline-item"><strong><?= e(ucfirst($h['status'])) ?></strong><small class="d-block text-muted-2"><?= e(format_datetime($h['created_at'])) ?></small><p class="small text-muted-2 mb-0"><?= e($h['catatan']??'') ?></p></div><?php endforeach; ?></div><?php if($p['alasan_penolakan']): ?><div class="alert alert-danger mt-2 mb-0">Alasan penolakan: <?= e($p['alasan_penolakan']) ?></div><?php endif; ?></div></div></section><?php endforeach; endif; ?></div>
